"use client";

import {
  Activity, ArrowDownRight, ArrowRight, ArrowUpRight, Bell, Boxes, BriefcaseBusiness,
  CalendarDays, Check, ChevronRight, CircleDollarSign,
  CircleAlert, ClipboardCheck, ClipboardPaste, Clock3, Download, FileBarChart, FileSpreadsheet, Filter, Gauge, HandCoins, History,
  Bot, FolderOpen, LayoutDashboard, Lightbulb, ListTodo, LoaderCircle, Menu, MoreHorizontal,
  Link2, PackagePlus, PanelLeftClose, Pencil, Plus, RefreshCw, Search, Settings,
  Sparkles, Tags, Target, Trash2, TrendingUp, Upload, UserRound, UsersRound, WalletCards, X,
} from "lucide-react";
import { FormEvent, ReactNode, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { AIAssistant, ApiIntegrations, DocumentsArea, TeamEditor, type CalendarEvent, type CentralDocument, type EventHistory, type EventParticipant, type TeamMember } from "./expansion-modules";
import { NativeCalendar, type ScheduledTask } from "./calendar-native";
import { LeadBaseV2, LeadStatusSettings } from "./lead-base-v2";
import { CENTRAL_TIME_ZONE, formatCentralTimestamp, toCentralDate } from "./timezone";

type Product = { id:number; name:string; category:string; description:string; price:number; promotionalPrice:number|null; minimumPrice:number; cost:number; status:string; deliveryDays:number; targetAudience:string; problemSolved:string; salesArguments:string; objections:string; notes:string; updatedAt:string };
type Lead = { id:number; name:string; company:string; phone:string; whatsapp:string; email:string; instagram:string; site:string; city:string; segment:string; source:string; productInterest:string; responsible:string; status:string; potentialValue:number; firstContact:string; lastContact:string; nextFollowup:string; notes:string; createdAt:string; updatedAt:string };
type Sale = { id:number; client:string; productId:number|null; productName:string; seller:string; grossValue:number; discount:number; finalValue:number; cost:number; paymentMethod:string; date:string; status:string; notes:string };
type Task = ScheduledTask;
type Goal = { id:number; name:string; scope:string; ownerName:string; periodType:string; revenueTarget:number; salesTarget:number; leadsTarget:number; meetingsTarget:number; proposalsTarget:number; startDate:string; endDate:string };
type AuditLog = { id:number; actor:string; action:string; entity:string; detail:string; createdAt:string };
type Niche = { id:number; name:string; description:string; color:string; status:string; defaultResponsible:string; recommendedProduct:string; updatedAt:string };
type ImportedLead = { id:number; batchId:number|null; name:string; company:string; nicheId:number|null; nicheName:string; phone:string; whatsapp:string; email:string; instagram:string; site:string; city:string; source:string; responsible:string; contactStatus:string; productInterest:string; potentialValue:number; nextFollowup:string; notes:string; pipelineLeadId:number|null; importedAt:string; updatedAt:string };
type ImportBatch = { id:number; fileName:string; source:string; importedBy:string; totalRows:number; importedRows:number; duplicateRows:number; skippedRows:number; errorRows:number; nichesFound:number; createdAt:string };
type ImportError = { id:number; batchId:number; rowNumber:number; error:string; rawData:string; createdAt:string };
type ContactHistory = { id:number; importedLeadId:number; actor:string; oldStatus:string; newStatus:string; note:string; createdAt:string };
type WorkspaceData = { products:Product[]; leads:Lead[]; sales:Sale[]; tasks:Task[]; goals:Goal[]; settings:Record<string,string>; auditLogs:AuditLog[]; niches:Niche[]; importedLeads:ImportedLead[]; importBatches:ImportBatch[]; importErrors:ImportError[]; contactHistory:ContactHistory[]; teamMembers:TeamMember[]; calendarEvents:CalendarEvent[]; eventParticipants:EventParticipant[]; eventHistory:EventHistory[]; documents:CentralDocument[]; currentMemberId:number|null; temporaryOpenAccess:boolean; syncedAt:string };
type ModalType = "product"|"lead"|"sale"|"task"|"goal"|null;

const navGroups = [
  { label:"Visão geral", items:[["Dashboard",LayoutDashboard],["Metas",Target],["Insights",Lightbulb]] },
  { label:"Comercial", items:[["Base de Leads",FileSpreadsheet],["Nichos",Tags],["Leads",UsersRound],["Pipeline",Gauge],["Clientes",BriefcaseBusiness],["Produtos",Boxes],["Vendas",HandCoins]] },
  { label:"Operação", items:[["Tarefas",ListTodo],["Follow-ups",RefreshCw],["Calendário",CalendarDays],["Documentos",FolderOpen]] },
  { label:"Análise", items:[["Financeiro",WalletCards],["Relatórios",FileBarChart],["Assistente IA",Bot],["API e Integrações",Link2],["Configurações",Settings]] },
] as const;
const leadStages = ["Novo","Contatado","Respondeu","Qualificado","Reunião marcada","Proposta enviada","Negociação","Ganho","Perdido"];
const pipelineStages = ["Novo","Contatado","Qualificado","Reunião marcada","Proposta enviada","Negociação","Ganho","Perdido"];
const contactStatuses = ["Não contatado","Contatado","Respondeu","Qualificado","Sem interesse","Número inválido","Recontatar depois"];
const todayISO = () => toCentralDate();
const money = (value:number) => new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL",maximumFractionDigits:0}).format(value||0);
const shortDate = (value:string) => value ? new Intl.DateTimeFormat("pt-BR",{day:"2-digit",month:"short",timeZone:"UTC"}).format(new Date(`${value}T12:00:00Z`)) : "—";
const dateTime = (value:string) => formatCentralTimestamp(value,{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"});
const pct = (value:number,target:number) => target>0 ? Math.min(100,Math.round(value/target*100)) : 0;
function startOfWeek(){ const copy=new Date(); const day=copy.getDay(); copy.setDate(copy.getDate()-(day===0?6:day-1)); return copy.toLocaleDateString("sv-SE",{timeZone:"America/Sao_Paulo"}); }
function startOfMonth(){ return `${new Date().toLocaleDateString("sv-SE",{timeZone:"America/Sao_Paulo"}).slice(0,7)}-01`; }

function Progress({value,target,tone="violet"}:{value:number;target:number;tone?:string}){ return <div className="progress-track"><span className={`progress-fill ${tone}`} style={{width:`${pct(value,target)}%`}} /></div>; }
function Empty({icon,title,text,action}:{icon:ReactNode;title:string;text:string;action?:ReactNode}){ return <div className="empty-state"><div className="empty-icon">{icon}</div><strong>{title}</strong><p>{text}</p>{action}</div>; }
function StatusBadge({children}:{children:ReactNode}){ const value=String(children); const tone=value.includes("Pago")||value.includes("Ganho")||value.includes("Conclu")||value.includes("Ativo")?"success":value.includes("Perdido")||value.includes("Cancel")||value.includes("Urgente")||value.includes("Atrasado")?"danger":value.includes("Pendente")||value.includes("Negociação")||value.includes("Alta")?"warning":"neutral"; return <span className={`status-badge ${tone}`}><i />{children}</span>; }
function MetricCard({label,value,detail,icon,accent="neutral"}:{label:string;value:string;detail:ReactNode;icon:ReactNode;accent?:string}){ return <article className={`metric-card ${accent}`}><div className="metric-head"><span>{label}</span><div className="metric-icon">{icon}</div></div><strong>{value}</strong><div className="metric-detail">{detail}</div></article>; }
function SectionHeader({eyebrow,title,text,actions}:{eyebrow?:string;title:string;text:string;actions?:ReactNode}){ return <div className="section-header"><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1><p>{text}</p></div>{actions&&<div className="section-actions">{actions}</div>}</div>; }

export default function CentralClient({initialUser,initialEmail}:{initialUser:string;initialEmail:string}){
  const [data,setData]=useState<WorkspaceData|null>(null); const [active,setActive]=useState("Dashboard");
  const [loading,setLoading]=useState(true); const [saving,setSaving]=useState(false); const [syncing,setSyncing]=useState(false); const [error,setError]=useState(""); const [toast,setToast]=useState("");
  const [modal,setModal]=useState<ModalType>(null); const [editing,setEditing]=useState<Product|Lead|Goal|null>(null); const [mobileNav,setMobileNav]=useState(false); const [compactNav,setCompactNav]=useState(false); const [search,setSearch]=useState(""); const [kanban,setKanban]=useState(false);
  const [notificationsOpen,setNotificationsOpen]=useState(false); const searchRef=useRef<HTMLInputElement>(null);

  const loadData=useCallback(async(quiet=false)=>{ if(!quiet)setLoading(true);setSyncing(true); try{ const response=await fetch("/api/workspace",{cache:"no-store"}); const result=await response.json() as WorkspaceData&{error?:string}; if(!response.ok)throw new Error(result.error||"Não foi possível carregar os dados."); setData(result); setError(""); }catch(err){setError(err instanceof Error?err.message:"Erro ao carregar os dados.");}finally{if(!quiet)setLoading(false);setSyncing(false);}},[]);
  useEffect(()=>{const initial=window.setTimeout(()=>void loadData(),0);const timer=window.setInterval(()=>void loadData(true),12000);return()=>{window.clearTimeout(initial);window.clearInterval(timer);};},[loadData]);
  useEffect(()=>{const shortcut=(event:KeyboardEvent)=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==="k"){event.preventDefault();searchRef.current?.focus();}};window.addEventListener("keydown",shortcut);return()=>window.removeEventListener("keydown",shortcut);},[]);
  useEffect(()=>{if(!toast)return;const timer=window.setTimeout(()=>setToast(""),3200);return()=>window.clearTimeout(timer);},[toast]);
  const api=async(method:"POST"|"PATCH"|"DELETE",body:Record<string,unknown>,success:string,onResult?:(result:Record<string,unknown>)=>void)=>{setSaving(true);try{const response=await fetch("/api/workspace",{method,headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const result=await response.json() as Record<string,unknown>&{error?:string};if(!response.ok)throw new Error(result.error||"Não foi possível salvar.");onResult?.(result);await loadData(true);setToast(success);return true;}catch(err){setToast(err instanceof Error?err.message:"Erro ao salvar.");return false;}finally{setSaving(false);}};

  const paidSales=useMemo(()=>data?.sales.filter(s=>s.status==="Pago")||[],[data]); const today=todayISO(); const weekStart=startOfWeek(); const monthStart=startOfMonth();
  const dailySales=paidSales.filter(s=>s.date===today), weeklySales=paidSales.filter(s=>s.date>=weekStart), monthlySales=paidSales.filter(s=>s.date>=monthStart);
  const dailyRevenue=dailySales.reduce((n,s)=>n+s.finalValue,0), weeklyRevenue=weeklySales.reduce((n,s)=>n+s.finalValue,0), monthlyRevenue=monthlySales.reduce((n,s)=>n+s.finalValue,0), monthlyCost=monthlySales.reduce((n,s)=>n+s.cost,0);
  const pipelineValue=(data?.leads||[]).filter(l=>!["Ganho","Perdido"].includes(l.status)).reduce((n,l)=>n+l.potentialValue,0);
  const dayGoal=data?.goals.find(g=>g.periodType==="Diária"&&g.scope==="Empresa"), weekGoal=data?.goals.find(g=>g.periodType==="Semanal"&&g.scope==="Empresa"), monthGoal=data?.goals.find(g=>g.periodType==="Mensal"&&g.scope==="Empresa");
  const overdue=(data?.leads||[]).filter(l=>l.nextFollowup&&l.nextFollowup<today&&!["Ganho","Perdido"].includes(l.status)); const todayFollowups=(data?.leads||[]).filter(l=>l.nextFollowup===today&&!["Ganho","Perdido"].includes(l.status)); const openTasks=(data?.tasks||[]).filter(t=>t.status!=="Concluída");
  const searchResults=useMemo(()=>{if(!data||search.trim().length<2)return[];const q=search.toLowerCase();const out:{type:string;title:string;subtitle:string;section:string}[]=[];data.importedLeads.filter(i=>`${i.name} ${i.company} ${i.email} ${i.whatsapp}`.toLowerCase().includes(q)).slice(0,4).forEach(i=>out.push({type:"Base",title:i.company||i.name,subtitle:i.nicheName||i.contactStatus,section:"Base de Leads"}));data.leads.filter(i=>`${i.name} ${i.company} ${i.email}`.toLowerCase().includes(q)).slice(0,4).forEach(i=>out.push({type:"Lead",title:i.name,subtitle:i.company||i.status,section:"Leads"}));data.products.filter(i=>`${i.name} ${i.category}`.toLowerCase().includes(q)).slice(0,4).forEach(i=>out.push({type:"Produto",title:i.name,subtitle:i.category,section:"Produtos"}));data.sales.filter(i=>`${i.client} ${i.productName}`.toLowerCase().includes(q)).slice(0,4).forEach(i=>out.push({type:"Venda",title:i.client,subtitle:i.productName,section:"Vendas"}));return out.slice(0,8);},[data,search]);
  const openModal=(type:ModalType,item:Product|Lead|Goal|null=null)=>{setEditing(item);setModal(type);}; const closeModal=()=>{if(!saving){setModal(null);setEditing(null);}};
  async function submitForm(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!modal)return;const values=Object.fromEntries(new FormData(event.currentTarget).entries());const feminine=["sale","task","goal"].includes(modal);const state=editing?(feminine?"atualizada":"atualizado"):(feminine?"criada":"criado");const ok=await api(editing?"PATCH":"POST",{entity:modal,...(editing?{id:editing.id}:{}),...values},`${modalLabel(modal)} ${state} com sucesso.`);if(ok)closeModal();}
  const update=(entity:string,id:number,fields:Record<string,unknown>,message="Atualizado com sucesso.")=>api("PATCH",{entity,id,...fields},message);
  const remove=async(entity:string,id:number,label:string)=>{if(!window.confirm(`Excluir ${label}? Esta ação não poderá ser desfeita.`))return;await api("DELETE",{entity,id},`${label} excluído.`);};
  const exportCsv=(kind:"leads"|"sales"|"products")=>{if(!data)return;const rows=data[kind];if(!rows.length){setToast("Não há dados para exportar.");return;}const headers=Object.keys(rows[0]);const csv=[headers.join(";"),...rows.map(row=>headers.map(h=>`"${String((row as unknown as Record<string,unknown>)[h]??"").replaceAll('"','""')}"`).join(";"))].join("\n");const blob=new Blob(["\ufeff",csv],{type:"text/csv;charset=utf-8"});const link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=`${kind}-${today}.csv`;link.click();URL.revokeObjectURL(link.href);setToast("Arquivo CSV gerado.");};
  if(loading)return <div className="boot-screen"><div className="brand-mark">C</div><LoaderCircle className="spin"/><p>Preparando seu centro de comando…</p></div>;

  return <div className={`app-shell ${compactNav?"compact":""}`}>
    <aside className={`sidebar ${mobileNav?"mobile-open":""}`}><div className="brand-row"><div className="brand-mark">C</div><div className="brand-copy"><strong>{data?.settings.companyName||"Central"}</strong><span>Operação comercial</span></div><button className="icon-button mobile-close" onClick={()=>setMobileNav(false)}><X size={19}/></button></div><nav>{navGroups.map(group=><div className="nav-group" key={group.label}><span className="nav-label">{group.label}</span>{group.items.map(([label,Icon])=><button key={label} className={`nav-item ${active===label?"active":""}`} onClick={()=>{setActive(label);setMobileNav(false);}}><Icon size={18}/><span>{label}</span>{active===label&&<i/>}</button>)}</div>)}</nav><div className="sidebar-bottom"><button className="nav-collapse" onClick={()=>setCompactNav(!compactNav)}><PanelLeftClose size={18}/><span>Recolher menu</span></button><div className="user-card"><div className="avatar">{initialUser.slice(0,1).toUpperCase()}</div><div><strong>{initialUser}</strong><span>{initialEmail||"Administrador"}</span></div><ChevronRight size={16}/></div></div></aside>
    <main className="main-area"><header className="topbar"><button aria-label="Abrir menu" className="icon-button menu-button" onClick={()=>setMobileNav(true)}><Menu size={21}/></button><div className="global-search"><Search size={18}/><input ref={searchRef} value={search} onChange={e=>setSearch(e.target.value)} placeholder="Pesquisar leads, clientes, produtos…"/><kbd>⌘ K</kbd>{searchResults.length>0&&<div className="search-popover">{searchResults.map((r,i)=><button key={`${r.type}-${i}`} onClick={()=>{setActive(r.section);setSearch("");}}><span>{r.type}</span><div><strong>{r.title}</strong><small>{r.subtitle}</small></div><ChevronRight size={15}/></button>)}</div>}</div><div className="top-actions"><button className={`sync-status ${error?"failed":syncing?"syncing":"ready"}`} onClick={()=>loadData(true)}><span/><b>{error?"Falha ao sincronizar":syncing?"Atualizando…":data?.syncedAt?`Atualizado ${formatCentralTimestamp(data.syncedAt,{hour:"2-digit",minute:"2-digit"})}`:"Atualizado"}</b></button><div className="notification-wrap"><button aria-label="Abrir notificações" aria-expanded={notificationsOpen} className="icon-button notification-button" onClick={()=>setNotificationsOpen(!notificationsOpen)}><Bell size={19}/>{overdue.length>0&&<i>{overdue.length}</i>}</button>{notificationsOpen&&<div className="notification-popover" role="dialog" aria-label="Notificações comerciais"><header><strong>Notificações</strong><button aria-label="Fechar notificações" onClick={()=>setNotificationsOpen(false)}><X size={16}/></button></header>{overdue.length||todayFollowups.length?<><p>{overdue.length} atrasado{overdue.length===1?"":"s"} · {todayFollowups.length} para hoje</p>{[...overdue,...todayFollowups].slice(0,6).map((lead)=><button key={lead.id} onClick={()=>{setActive("Follow-ups");setNotificationsOpen(false);}}><Clock3 size={15}/><span><strong>{lead.company||lead.name}</strong><small>{lead.nextFollowup<today?"Follow-up atrasado":"Follow-up de hoje"}</small></span><ChevronRight size={15}/></button>)}<button className="notification-all" onClick={()=>{setActive("Follow-ups");setNotificationsOpen(false);}}>Ver todos os follow-ups</button></>:<div className="notification-empty"><Check size={18}/><span>Nenhuma pendência agora.</span></div>}</div>}</div><button className="primary-button" onClick={()=>openModal("sale")}><Plus size={18}/>Nova venda</button></div></header>
      <div className="content-wrap">{error&&<div className="error-banner"><span>{error}</span><button onClick={()=>loadData()}>Tentar novamente</button></div>}{data?.temporaryOpenAccess&&<div className="temporary-access-banner"><CircleAlert size={17}/><span>Acesso temporariamente aberto a usuários autenticados. Administração e exclusões permanecem restritas.</span></div>}
        {active==="Dashboard"&&<Dashboard data={data} user={initialUser} dailyRevenue={dailyRevenue} weeklyRevenue={weeklyRevenue} monthlyRevenue={monthlyRevenue} dailySales={dailySales} monthlySales={monthlySales} dayGoal={dayGoal} weekGoal={weekGoal} monthGoal={monthGoal} pipelineValue={pipelineValue} overdue={overdue} todayFollowups={todayFollowups} tasks={openTasks} openModal={openModal} setActive={setActive}/>}
        {active==="Base de Leads"&&<LeadBaseV2 data={data} api={api} saving={saving} user={initialUser} setActive={setActive}/>} {active==="Nichos"&&<Niches data={data} api={api} saving={saving}/>} {active==="Produtos"&&<Products data={data} openModal={openModal} remove={remove}/>} {active==="Leads"&&<Leads data={data} kanban={kanban} setKanban={setKanban} openModal={openModal} update={update} remove={remove}/>} {active==="Pipeline"&&<Pipeline data={data} update={update} openModal={openModal}/>} {active==="Vendas"&&<Sales data={data} openModal={openModal} update={update} remove={remove}/>} {active==="Metas"&&<Goals data={data} paidSales={paidSales} openModal={openModal} remove={remove}/>} {active==="Tarefas"&&<Tasks data={data} openModal={openModal} update={update} remove={remove}/>} {active==="Follow-ups"&&<Followups data={data} today={today} update={update} openModal={openModal}/>} {active==="Clientes"&&<Customers data={data}/>} {active==="Financeiro"&&<Finance data={data} revenue={monthlyRevenue} cost={monthlyCost} profit={monthlyRevenue-monthlyCost}/>} {active==="Calendário"&&<NativeCalendar teamMembers={data?.teamMembers||[]} calendarEvents={data?.calendarEvents||[]} eventParticipants={data?.eventParticipants||[]} eventHistory={data?.eventHistory||[]} tasks={data?.tasks||[]} leads={data?.leads||[]} currentMemberId={data?.currentMemberId||null} refresh={()=>loadData(true)} notify={setToast}/>} {active==="Documentos"&&<DocumentsArea documents={data?.documents||[]} refresh={()=>loadData(true)} notify={setToast}/>} {active==="Relatórios"&&<Reports data={data} exportCsv={exportCsv}/>} {active==="Insights"&&<Insights data={data} monthlyRevenue={monthlyRevenue} monthlyProfit={monthlyRevenue-monthlyCost} pipelineValue={pipelineValue} monthGoal={monthGoal}/>} {active==="Assistente IA"&&<AIAssistant/>} {active==="API e Integrações"&&<ApiIntegrations onOpenAssistant={()=>setActive("Assistente IA")}/>} {active==="Configurações"&&<Configuration data={data} api={api} user={initialUser}/>}
      </div></main>
    {modal&&<RecordModal type={modal} editing={editing} products={data?.products||[]} user={initialUser} saving={saving} close={closeModal} submit={submitForm}/>} {toast&&<div className="toast"><Check size={18}/><span>{toast}</span></div>} {mobileNav&&<button className="nav-scrim" onClick={()=>setMobileNav(false)}/>}
  </div>;
}

type ApiFn = (method:"POST"|"PATCH"|"DELETE",body:Record<string,unknown>,success:string,onResult?:(result:Record<string,unknown>)=>void)=>Promise<boolean>;
const importFields = [
  ["ignore","Ignorar coluna"],["company","Empresa"],["name","Nome"],["nicheName","Nicho"],["phone","Telefone"],["whatsapp","WhatsApp"],["email","E-mail"],["instagram","Instagram"],["site","Site"],["city","Cidade"],["source","Origem"],["responsible","Responsável"],["productInterest","Produto de interesse"],["potentialValue","Valor potencial"],["nextFollowup","Próximo follow-up"],["notes","Observações"],
] as const;
const importAliases:Record<string,string[]> = {
  company:["empresa","company","razao social","estabelecimento"],name:["nome","contato","responsavel","name"],nicheName:["nicho","segmento","categoria","ramo"],phone:["telefone","fone","phone"],whatsapp:["whatsapp","whats","celular"],email:["email","e-mail","mail"],instagram:["instagram","insta"],site:["site","website","url"],city:["cidade","municipio","city"],source:["origem","source","fonte"],responsible:["vendedor","responsavel","owner"],productInterest:["produto","interesse","servico"],potentialValue:["valor","potencial","ticket"],nextFollowup:["followup","follow-up","proximo contato"],notes:["observacao","observacoes","notas","notes"],
};
const normalizeLabel=(value:string)=>value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g," ").trim();
const inferField=(header:string)=>{const normalized=normalizeLabel(header);return Object.entries(importAliases).find(([,aliases])=>aliases.some(alias=>normalized===normalizeLabel(alias)||normalized.includes(normalizeLabel(alias))))?.[0]||"ignore";};
const normalizePhone=(value:string)=>value.replace(/\D/g,"");
const normalizeContact=(value:string)=>value.toLowerCase().replace(/^https?:\/\//,"").replace(/\/$/,"").trim();

// Mantido como referência de compatibilidade durante a migração da interface.
// eslint-disable-next-line @typescript-eslint/no-unused-vars
function LeadBase({data,api,saving,user,setActive}:{data:WorkspaceData|null;api:ApiFn;saving:boolean;user:string;setActive:(v:string)=>void}){
  const leads=useMemo(()=>data?.importedLeads||[],[data?.importedLeads]),niches=data?.niches||[];
  const[query,setQuery]=useState("");const[niche,setNiche]=useState("");const[status,setStatus]=useState("");const[city,setCity]=useState("");
  const[selected,setSelected]=useState<number[]>([]);const[importOpen,setImportOpen]=useState(false);const[editing,setEditing]=useState<ImportedLead|null>(null);const[manualOpen,setManualOpen]=useState(false);const[pipelineLead,setPipelineLead]=useState<ImportedLead|null>(null);
  const cities=useMemo(()=>Array.from(new Set(leads.map(item=>item.city).filter(Boolean))).sort(),[leads]);
  const filtered=useMemo(()=>leads.filter(item=>{const hay=`${item.name} ${item.company} ${item.email} ${item.whatsapp} ${item.phone} ${item.instagram}`.toLowerCase();return(!query||hay.includes(query.toLowerCase()))&&(!niche||String(item.nicheId)===niche)&&(!status||item.contactStatus===status)&&(!city||item.city===city);}),[leads,query,niche,status,city]);
  const allVisible=filtered.length>0&&filtered.every(item=>selected.includes(item.id));
  const bulk=async(field:"contactStatus"|"nicheId",value:string)=>{if(!value||!selected.length)return;const ok=await api("POST",{entity:"bulkImportedLead",ids:selected,[field]:field==="nicheId"?Number(value):value},`${selected.length} leads atualizados.`);if(ok)setSelected([]);};
  const exportRows=(rows:ImportedLead[])=>{if(!rows.length)return;const headers=["Empresa","Nome","Nicho","Telefone","WhatsApp","E-mail","Instagram","Site","Cidade","Origem","Responsável","Status","Pipeline"];
    const values=rows.map(item=>[item.company,item.name,item.nicheName,item.phone,item.whatsapp,item.email,item.instagram,item.site,item.city,item.source,item.responsible,item.contactStatus,item.pipelineLeadId?"Sim":"Não"]);const csv=[headers,...values].map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(";")).join("\n");const link=document.createElement("a");link.href=URL.createObjectURL(new Blob(["\ufeff",csv],{type:"text/csv;charset=utf-8"}));link.download=`base-de-leads-${todayISO()}.csv`;link.click();URL.revokeObjectURL(link.href);};
  return <><SectionHeader eyebrow="PROSPECÇÃO" title="Base de Leads" text="Importe, organize e qualifique contatos antes de enviar oportunidades para o funil." actions={<><button className="secondary-button" onClick={()=>setManualOpen(true)}><Plus size={17}/>Adicionar lead</button><button className="primary-button" onClick={()=>setImportOpen(true)}><Upload size={17}/>Importar lista</button></>}/>
    <div className="metrics-grid lead-base-metrics"><MetricCard label="Leads na base" value={String(leads.length)} detail={`${new Set(leads.map(item=>item.nicheName)).size} nichos`} icon={<FileSpreadsheet size={19}/>} accent="violet"/><MetricCard label="Não contatados" value={String(leads.filter(item=>item.contactStatus==="Não contatado").length)} detail="Prontos para prospecção" icon={<Clock3 size={19}/>} accent="amber"/><MetricCard label="Contatados" value={String(leads.filter(item=>item.contactStatus!=="Não contatado").length)} detail="Com atividade registrada" icon={<ClipboardCheck size={19}/>} accent="blue"/><MetricCard label="Na pipeline" value={String(leads.filter(item=>item.pipelineLeadId).length)} detail="Oportunidades criadas" icon={<Link2 size={19}/>} accent="green"/></div>
    <div className="base-toolbar"><div className="base-search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar empresa, contato, e-mail…"/></div><div className="base-filter"><Filter size={15}/><select value={niche} onChange={e=>setNiche(e.target.value)}><option value="">Todos os nichos</option>{niches.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">Todos os status</option>{contactStatuses.map(item=><option key={item}>{item}</option>)}</select><select value={city} onChange={e=>setCity(e.target.value)}><option value="">Todas as cidades</option>{cities.map(item=><option key={item}>{item}</option>)}</select></div><button className="secondary-button" onClick={()=>exportRows(filtered)}><Download size={16}/>Exportar</button></div>
    {selected.length>0&&<div className="bulk-bar"><strong>{selected.length} selecionado{selected.length>1?"s":""}</strong><select defaultValue="" onChange={e=>{void bulk("contactStatus",e.target.value);e.currentTarget.value="";}}><option value="" disabled>Alterar status</option>{contactStatuses.map(item=><option key={item}>{item}</option>)}</select><select defaultValue="" onChange={e=>{void bulk("nicheId",e.target.value);e.currentTarget.value="";}}><option value="" disabled>Alterar nicho</option>{niches.filter(item=>item.status==="Ativo").map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><button onClick={()=>exportRows(leads.filter(item=>selected.includes(item.id)))}><Download size={15}/>Exportar seleção</button><button onClick={()=>setSelected([])}><X size={15}/></button></div>}
    {!filtered.length?<div className="panel"><Empty icon={<FileSpreadsheet size={27}/>} title={leads.length?"Nenhum lead corresponde aos filtros":"Sua base de prospecção está vazia"} text={leads.length?"Ajuste a busca ou limpe os filtros para ver outros contatos.":"Importe Excel, CSV ou cole uma tabela para disponibilizar a lista à equipe."} action={!leads.length?<button className="primary-button" onClick={()=>setImportOpen(true)}><Upload size={16}/>Importar primeira lista</button>:undefined}/></div>:<>
      <div className="table-panel lead-base-table"><table><thead><tr><th><input type="checkbox" checked={allVisible} onChange={()=>setSelected(allVisible?selected.filter(id=>!filtered.some(item=>item.id===id)):Array.from(new Set([...selected,...filtered.map(item=>item.id)])))}/></th><th>Empresa / contato</th><th>Nicho</th><th>Contato</th><th>Responsável</th><th>Status</th><th>Pipeline</th><th/></tr></thead><tbody>{filtered.map(item=><tr key={item.id}><td><input type="checkbox" checked={selected.includes(item.id)} onChange={()=>setSelected(current=>current.includes(item.id)?current.filter(id=>id!==item.id):[...current,item.id])}/></td><td><div className="person-cell"><div className="avatar small">{(item.company||item.name||"L").slice(0,1)}</div><div><strong>{item.company||item.name}</strong><span>{item.name&&item.company?item.name:item.city||"Sem cidade"}</span></div></div></td><td><span className="niche-pill"><i style={{background:niches.find(n=>n.id===item.nicheId)?.color||"#aaa"}}/>{item.nicheName}</span></td><td><strong>{item.whatsapp||item.phone||item.email||"—"}</strong><span className="cell-note">{item.email&&item.whatsapp?item.email:item.source}</span></td><td>{item.responsible||"—"}</td><td><select className="status-select" value={item.contactStatus} onChange={e=>api("PATCH",{entity:"importedLead",id:item.id,contactStatus:e.target.value},"Status de prospecção atualizado.")}>{contactStatuses.map(value=><option key={value}>{value}</option>)}</select></td><td>{item.pipelineLeadId?<button className="pipeline-linked" onClick={()=>setActive("Pipeline")}><Check size={14}/>Na pipeline</button>:<button className="pipeline-add" onClick={()=>setPipelineLead(item)}>Adicionar <ArrowRight size={14}/></button>}</td><td><button className="table-delete" onClick={()=>setEditing(item)}><Pencil size={15}/></button></td></tr>)}</tbody></table></div>
      <div className="lead-mobile-cards">{filtered.map(item=><article className="lead-mobile-card" key={item.id}><div className="lead-mobile-head"><label><input type="checkbox" checked={selected.includes(item.id)} onChange={()=>setSelected(current=>current.includes(item.id)?current.filter(id=>id!==item.id):[...current,item.id])}/><span>{item.company||item.name}</span></label><button onClick={()=>setEditing(item)}><Pencil size={15}/></button></div><span className="niche-pill"><i style={{background:niches.find(n=>n.id===item.nicheId)?.color||"#aaa"}}/>{item.nicheName}</span><p>{item.whatsapp||item.phone||item.email||"Sem canal de contato"}</p><select className="status-select" value={item.contactStatus} onChange={e=>api("PATCH",{entity:"importedLead",id:item.id,contactStatus:e.target.value},"Status atualizado.")}>{contactStatuses.map(value=><option key={value}>{value}</option>)}</select>{item.pipelineLeadId?<button className="pipeline-linked" onClick={()=>setActive("Pipeline")}><Check size={14}/>Ver na pipeline</button>:<button className="pipeline-add" onClick={()=>setPipelineLead(item)}>Adicionar à pipeline <ArrowRight size={14}/></button>}</article>)}</div></>}
    {(data?.importBatches.length||0)>0&&<article className="panel batch-panel"><div className="panel-head"><div><span>RASTREABILIDADE</span><h2>Importações recentes</h2></div><History size={19}/></div><div className="batch-list">{data?.importBatches.slice(0,5).map(batch=><div key={batch.id}><FileSpreadsheet size={17}/><div><strong>{batch.fileName}</strong><span>{batch.importedBy} · {dateTime(batch.createdAt)}</span></div><b>{batch.importedRows} importados</b>{batch.duplicateRows>0&&<em>{batch.duplicateRows} duplicados</em>}{batch.errorRows>0&&<em className="error-count">{batch.errorRows} erros</em>}</div>)}</div></article>}
    {importOpen&&<LeadImportModal current={leads} api={api} saving={saving} close={()=>setImportOpen(false)}/>} {(manualOpen||editing)&&<BaseLeadModal lead={editing} niches={niches} history={data?.contactHistory||[]} user={user} api={api} saving={saving} close={()=>{setManualOpen(false);setEditing(null);}}/>} {pipelineLead&&<PipelineFromBaseModal lead={pipelineLead} products={data?.products||[]} user={user} api={api} saving={saving} close={()=>setPipelineLead(null)} setActive={setActive}/>} </>;
}

function LeadImportModal({current,api,saving,close}:{current:ImportedLead[];api:ApiFn;saving:boolean;close:()=>void}){
  const[step,setStep]=useState(1);const[mode,setMode]=useState<"file"|"paste">("file");const[rawRows,setRawRows]=useState<Record<string,string>[]>([]);const[fileName,setFileName]=useState("");const[paste,setPaste]=useState("");const[mapping,setMapping]=useState<Record<string,string>>({});const[strategy,setStrategy]=useState("skip");const[localError,setLocalError]=useState("");
  const headers=useMemo(()=>rawRows[0]?Object.keys(rawRows[0]):[],[rawRows]);
  const mappedRows=useMemo(()=>rawRows.map(row=>{const out:Record<string,string|number>={};headers.forEach(header=>{const field=mapping[header];if(field&&field!=="ignore")out[field]=String(row[header]??"").trim();});const rawValue=String(out.potentialValue||"").replace(/[^0-9,.-]/g,"");if(rawValue)out.potentialValue=Number(rawValue.includes(",")?rawValue.replace(/\./g,"").replace(",","."):rawValue)||0;return out;}),[rawRows,headers,mapping]);
  const validRows=mappedRows.filter(row=>row.name||row.company);const invalidRows=mappedRows.length-validRows.length;
  const duplicateCount=useMemo(()=>validRows.filter(row=>current.some(item=>{const email=normalizeContact(String(row.email||"")),phone=normalizePhone(String(row.phone||"")),whatsapp=normalizePhone(String(row.whatsapp||"")),site=normalizeContact(String(row.site||"")),instagram=normalizeContact(String(row.instagram||"")),company=normalizeContact(String(row.company||""));return(email&&normalizeContact(item.email)===email)||(phone&&normalizePhone(item.phone)===phone)||(whatsapp&&normalizePhone(item.whatsapp)===whatsapp)||(site&&normalizeContact(item.site)===site)||(instagram&&normalizeContact(item.instagram)===instagram)||(company&&normalizeContact(item.company)===company);})).length,[validRows,current]);
  const parseWorkbook=async(buffer:ArrayBuffer|string,name:string,type:"array"|"string")=>{try{setLocalError("");const XLSX=await import("xlsx");const workbook=XLSX.read(buffer,{type,cellDates:true});const sheet=workbook.Sheets[workbook.SheetNames[0]];const parsed=XLSX.utils.sheet_to_json<Record<string,unknown>>(sheet,{defval:"",raw:false}).slice(0,2000).map(row=>Object.fromEntries(Object.entries(row).map(([key,value])=>[String(key).trim(),String(value??"").trim()])));if(!parsed.length)throw new Error("A lista não possui linhas de dados.");const columns=Object.keys(parsed[0]);setRawRows(parsed);setFileName(name);setMapping(Object.fromEntries(columns.map(header=>[header,inferField(header)])));setStep(2);}catch(error){setLocalError(error instanceof Error?error.message:"Não foi possível ler a lista.");}};
  const submit=async()=>{const ok=await api("POST",{entity:"leadImport",rows:validRows,fileName:fileName||"Colagem manual",source:mode==="file"?"Arquivo":"Colagem",duplicateStrategy:strategy},`${validRows.length} linhas processadas na Base de Leads.`);if(ok)close();};
  return <div className="modal-layer" role="dialog" aria-modal="true"><button className="modal-scrim" onClick={close}/><div className="modal-card import-modal"><header><div><span>IMPORTAÇÃO · ETAPA {step} DE 3</span><h2>Adicionar lista à Base de Leads</h2></div><button onClick={close}><X size={20}/></button></header><div className="import-steps"><i className={step>=1?"active":""}>1</i><span/><i className={step>=2?"active":""}>2</i><span/><i className={step>=3?"active":""}>3</i></div>
    {step===1&&<div className="import-body"><div className="import-tabs"><button className={mode==="file"?"active":""} onClick={()=>setMode("file")}><FileSpreadsheet size={17}/>Excel ou CSV</button><button className={mode==="paste"?"active":""} onClick={()=>setMode("paste")}><ClipboardPaste size={17}/>Colar dados</button></div>{mode==="file"?<label className="drop-zone"><Upload size={30}/><strong>Selecione uma planilha</strong><span>XLSX, XLS ou CSV · até 5 MB · máximo 2.000 linhas</span><input type="file" accept=".xlsx,.xls,.csv" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>5*1024*1024){setLocalError("O arquivo excede o limite de 5 MB.");return;}await parseWorkbook(await file.arrayBuffer(),file.name,"array");}}/></label>:<><textarea className="paste-area" value={paste} onChange={e=>setPaste(e.target.value)} placeholder={'Cole aqui a tabela com cabeçalhos. Ex.:\nEmpresa\tNome\tWhatsApp\tNicho'}/><button className="primary-button paste-continue" disabled={!paste.trim()} onClick={()=>void parseWorkbook(paste,"Colagem manual","string")}><ArrowRight size={16}/>Continuar</button></>}{localError&&<div className="import-error"><CircleAlert size={16}/>{localError}</div>}</div>}
    {step===2&&<div className="import-body"><div className="import-summary"><div><strong>{rawRows.length}</strong><span>linhas encontradas</span></div><div><strong>{headers.length}</strong><span>colunas</span></div><div><strong>{invalidRows}</strong><span>sem nome/empresa</span></div></div><h3>Mapeie as colunas</h3><p className="help-text">Confirme onde cada coluna da planilha deve entrar no sistema.</p><div className="mapping-grid">{headers.map(header=><label key={header}><span title={header}>{header}</span><ArrowRight size={14}/><select value={mapping[header]||"ignore"} onChange={e=>setMapping({...mapping,[header]:e.target.value})}>{importFields.map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label>)}</div><div className="import-footer"><button className="secondary-button" onClick={()=>setStep(1)}>Voltar</button><button className="primary-button" disabled={!validRows.length} onClick={()=>setStep(3)}>Validar e revisar <ArrowRight size={16}/></button></div></div>}
    {step===3&&<div className="import-body"><div className="validation-strip"><div className="success"><Check size={17}/><strong>{validRows.length} válidos</strong></div>{duplicateCount>0&&<div className="warning"><CircleAlert size={17}/><strong>{duplicateCount} possíveis duplicados</strong></div>}{invalidRows>0&&<div className="danger"><X size={17}/><strong>{invalidRows} ignorados</strong></div>}</div>{duplicateCount>0&&<label className="duplicate-choice">Ao encontrar duplicados<select value={strategy} onChange={e=>setStrategy(e.target.value)}><option value="skip">Ignorar duplicado</option><option value="fill">Preencher somente campos vazios</option><option value="keep">Manter como novo registro</option></select></label>}<div className="preview-table"><table><thead><tr><th>Empresa / Nome</th><th>Nicho</th><th>Contato</th><th>Cidade</th></tr></thead><tbody>{validRows.slice(0,8).map((row,index)=><tr key={index}><td><strong>{String(row.company||row.name)}</strong><span>{String(row.name||"")}</span></td><td>{String(row.nicheName||"Sem nicho")}</td><td>{String(row.whatsapp||row.phone||row.email||"—")}</td><td>{String(row.city||"—")}</td></tr>)}</tbody></table></div><p className="help-text">Prévia das primeiras {Math.min(8,validRows.length)} linhas. A lista será compartilhada com toda a equipe.</p><div className="import-footer"><button className="secondary-button" onClick={()=>setStep(2)}>Voltar</button><button className="primary-button" disabled={saving||!validRows.length} onClick={()=>void submit()}>{saving?<LoaderCircle className="spin" size={17}/>:<Upload size={17}/>} Importar {validRows.length} leads</button></div></div>}
  </div></div>;
}

function BaseLeadModal({lead,niches,history,user,api,saving,close}:{lead:ImportedLead|null;niches:Niche[];history:ContactHistory[];user:string;api:ApiFn;saving:boolean;close:()=>void}){const value=(key:keyof ImportedLead)=>String(lead?.[key]??"");const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget).entries());const ok=await api(lead?"PATCH":"POST",{entity:"importedLead",...(lead?{id:lead.id}:{}),...values},lead?"Lead da base atualizado.":"Lead adicionado à base.");if(ok)close();};return <div className="modal-layer" role="dialog" aria-modal="true"><button className="modal-scrim" onClick={close}/><div className="modal-card"><header><div><span>{lead?"FICHA DO LEAD":"CADASTRO MANUAL"}</span><h2>{lead?lead.company||lead.name:"Novo lead na base"}</h2></div><button onClick={close}><X size={20}/></button></header><form onSubmit={submit}><div className="form-grid"><label>Empresa<input name="company" defaultValue={value("company")} autoFocus/></label><label>Nome do contato<input name="name" defaultValue={value("name")}/></label><label>Nicho<select name="nicheId" defaultValue={value("nicheId")}><option value="">Sem nicho</option>{niches.filter(item=>item.status==="Ativo"||item.id===lead?.nicheId).map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label>Status<select name="contactStatus" defaultValue={value("contactStatus")||"Não contatado"}>{contactStatuses.map(item=><option key={item}>{item}</option>)}</select></label><label>WhatsApp<input name="whatsapp" defaultValue={value("whatsapp")}/></label><label>Telefone<input name="phone" defaultValue={value("phone")}/></label><label>E-mail<input type="email" name="email" defaultValue={value("email")}/></label><label>Instagram<input name="instagram" defaultValue={value("instagram")}/></label><label>Site<input name="site" defaultValue={value("site")}/></label><label>Cidade<input name="city" defaultValue={value("city")}/></label><label>Origem<input name="source" defaultValue={value("source")||"Cadastro manual"}/></label><label>Responsável<input name="responsible" defaultValue={value("responsible")||user}/></label><label>Produto de interesse<input name="productInterest" defaultValue={value("productInterest")}/></label><label>Valor potencial<input type="number" step="0.01" min="0" name="potentialValue" defaultValue={value("potentialValue")}/></label><label>Próximo follow-up<input type="date" name="nextFollowup" defaultValue={value("nextFollowup")}/></label><label className="full">Observações<textarea name="notes" defaultValue={value("notes")}/></label></div>{lead&&history.some(item=>item.importedLeadId===lead.id)&&<div className="lead-history"><strong>Histórico de contato</strong>{history.filter(item=>item.importedLeadId===lead.id).slice(0,6).map(item=><div key={item.id}><i/><span>{item.actor} alterou de <b>{item.oldStatus}</b> para <b>{item.newStatus}</b></span><time>{dateTime(item.createdAt)}</time></div>)}</div>}<footer><button type="button" className="secondary-button" onClick={close}>Cancelar</button><button className="primary-button" disabled={saving}>{saving?<LoaderCircle className="spin" size={17}/>:<Check size={17}/>} Salvar</button></footer></form></div></div>;}

function PipelineFromBaseModal({lead,products,user,api,saving,close,setActive}:{lead:ImportedLead;products:Product[];user:string;api:ApiFn;saving:boolean;close:()=>void;setActive:(v:string)=>void}){const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget).entries());const ok=await api("POST",{entity:"pipelineFromBase",id:lead.id,...values},"Oportunidade adicionada à pipeline.");if(ok){close();setActive("Pipeline");}};return <div className="modal-layer" role="dialog" aria-modal="true"><button className="modal-scrim" onClick={close}/><div className="modal-card pipeline-modal"><header><div><span>BASE DE LEADS → PIPELINE</span><h2>Criar oportunidade</h2></div><button onClick={close}><X size={20}/></button></header><div className="conversion-source"><div className="avatar">{(lead.company||lead.name).slice(0,1)}</div><div><strong>{lead.company||lead.name}</strong><span>{lead.nicheName} · {lead.whatsapp||lead.email||"sem contato"}</span></div></div><form onSubmit={submit}><div className="form-grid"><label>Etapa inicial<select name="status" defaultValue="Novo">{pipelineStages.filter(item=>item!=="Ganho").map(item=><option key={item}>{item}</option>)}</select></label><label>Responsável<input name="responsible" defaultValue={lead.responsible||user}/></label><label>Produto de interesse<input name="productInterest" defaultValue={lead.productInterest} list="pipeline-products"/><datalist id="pipeline-products">{products.map(item=><option key={item.id} value={item.name}/>)}</datalist></label><label>Valor potencial<input name="potentialValue" type="number" step="0.01" min="0" defaultValue={lead.potentialValue}/></label><label>Próximo follow-up<input name="nextFollowup" type="date" defaultValue={lead.nextFollowup}/></label><label className="full">Observações adicionais<textarea name="notes"/></label></div><div className="conversion-note"><CircleAlert size={17}/><p>O lead continuará visível na base e ficará vinculado à nova oportunidade, evitando conversões duplicadas.</p></div><footer><button type="button" className="secondary-button" onClick={close}>Cancelar</button><button className="primary-button" disabled={saving}>{saving?<LoaderCircle className="spin" size={17}/>:<ArrowRight size={17}/>} Criar na pipeline</button></footer></form></div></div>;}

function Niches({data,api,saving}:{data:WorkspaceData|null;api:ApiFn;saving:boolean}){const niches=data?.niches||[],leads=data?.importedLeads||[];const[open,setOpen]=useState(false);const[editing,setEditing]=useState<Niche|null>(null);const remove=async(item:Niche)=>{const used=leads.filter(lead=>lead.nicheId===item.id).length;let replacementNicheId:number|undefined;if(used){const choices=niches.filter(niche=>niche.id!==item.id);if(!choices.length){window.alert("Crie outro nicho antes de excluir este, pois há leads vinculados.");return;}const name=window.prompt(`Este nicho possui ${used} leads. Digite o nome do nicho de destino:\n${choices.map(niche=>niche.name).join(" · ")}`);const replacement=choices.find(niche=>niche.name.toLowerCase()===name?.trim().toLowerCase());if(!replacement){if(name)window.alert("Nicho de destino não encontrado.");return;}replacementNicheId=replacement.id;}if(!window.confirm(`Excluir o nicho ${item.name}?${used?" Os leads serão reatribuídos.":""}`))return;await api("DELETE",{entity:"niche",id:item.id,replacementNicheId},"Nicho excluído com segurança.");};return <><SectionHeader eyebrow="ORGANIZAÇÃO" title="Nichos" text="Crie classificações reutilizáveis e defina padrões para a prospecção." actions={<button className="primary-button" onClick={()=>setOpen(true)}><Plus size={17}/>Novo nicho</button>}/>{niches.length?<div className="niche-grid">{niches.map(item=>{const total=leads.filter(lead=>lead.nicheId===item.id).length;return <article className="niche-card" key={item.id}><div className="niche-card-top"><i style={{background:item.color}}/><StatusBadge>{item.status}</StatusBadge><div><button onClick={()=>setEditing(item)}><Pencil size={15}/></button><button onClick={()=>void remove(item)}><Trash2 size={15}/></button></div></div><h2>{item.name}</h2><p>{item.description||"Sem descrição"}</p><div className="niche-card-count"><strong>{total}</strong><span>leads vinculados</span></div><div className="niche-defaults"><span>Responsável <b>{item.defaultResponsible||"Não definido"}</b></span><span>Produto indicado <b>{item.recommendedProduct||"Não definido"}</b></span></div></article>;})}</div>:<div className="panel"><Empty icon={<Tags size={27}/>} title="Nenhum nicho cadastrado" text="Crie nichos para segmentar a Base de Leads e automatizar responsável e produto recomendado." action={<button className="primary-button" onClick={()=>setOpen(true)}><Plus size={16}/>Criar nicho</button>}/></div>}{(open||editing)&&<NicheModal niche={editing} products={data?.products||[]} api={api} saving={saving} close={()=>{setOpen(false);setEditing(null);}}/>}</>;}

function NicheModal({niche,products,api,saving,close}:{niche:Niche|null;products:Product[];api:ApiFn;saving:boolean;close:()=>void}){const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget).entries());const ok=await api(niche?"PATCH":"POST",{entity:"niche",...(niche?{id:niche.id}:{}),...values},niche?"Nicho atualizado.":"Nicho criado.");if(ok)close();};return <div className="modal-layer" role="dialog" aria-modal="true"><button className="modal-scrim" onClick={close}/><div className="modal-card"><header><div><span>{niche?"EDITAR NICHO":"NOVA CLASSIFICAÇÃO"}</span><h2>{niche?`Editar ${niche.name}`:"Criar nicho"}</h2></div><button onClick={close}><X size={20}/></button></header><form onSubmit={submit}><div className="form-grid"><label>Nome<input name="name" defaultValue={niche?.name||""} required autoFocus/></label><label>Cor<input className="color-input" type="color" name="color" defaultValue={niche?.color||"#6d5dfc"}/></label><label>Status<select name="status" defaultValue={niche?.status||"Ativo"}><option>Ativo</option><option>Inativo</option></select></label><label>Responsável padrão<input name="defaultResponsible" defaultValue={niche?.defaultResponsible||""}/></label><label className="full">Produto recomendado<input name="recommendedProduct" defaultValue={niche?.recommendedProduct||""} list="niche-products"/><datalist id="niche-products">{products.map(item=><option key={item.id} value={item.name}/>)}</datalist></label><label className="full">Descrição<textarea name="description" defaultValue={niche?.description||""}/></label></div><footer><button type="button" className="secondary-button" onClick={close}>Cancelar</button><button className="primary-button" disabled={saving}>{saving?<LoaderCircle className="spin" size={17}/>:<Check size={17}/>} Salvar nicho</button></footer></form></div></div>;}

function Dashboard({data,user,dailyRevenue,weeklyRevenue,monthlyRevenue,dailySales,monthlySales,dayGoal,weekGoal,monthGoal,pipelineValue,overdue,todayFollowups,tasks,openModal,setActive}:{data:WorkspaceData|null;user:string;dailyRevenue:number;weeklyRevenue:number;monthlyRevenue:number;dailySales:Sale[];monthlySales:Sale[];dayGoal?:Goal;weekGoal?:Goal;monthGoal?:Goal;pipelineValue:number;overdue:Lead[];todayFollowups:Lead[];tasks:Task[];openModal:(type:ModalType)=>void;setActive:(v:string)=>void}){
  const first=user.split(" ")[0], avg=monthlySales.length?monthlyRevenue/monthlySales.length:0, daysPassed=new Date().getDate(), daysTotal=new Date(new Date().getFullYear(),new Date().getMonth()+1,0).getDate(), projection=daysPassed?monthlyRevenue/daysPassed*daysTotal:0, dailyTarget=dayGoal?.revenueTarget||0, monthTarget=monthGoal?.revenueTarget||0, leads=data?.leads||[], conversion=leads.length?Math.round(leads.filter(l=>l.status==="Ganho").length/leads.length*100):0, chart=lastSevenDays(data?.sales||[]), hour=Number(new Intl.DateTimeFormat("pt-BR",{hour:"2-digit",hourCycle:"h23",timeZone:CENTRAL_TIME_ZONE}).format(new Date())), greeting=hour<12?"Bom dia":hour<18?"Boa tarde":"Boa noite";
  return <><SectionHeader eyebrow="CENTRO DE COMANDO" title={`${greeting}, ${first}.`} text={new Intl.DateTimeFormat("pt-BR",{weekday:"long",day:"2-digit",month:"long",timeZone:CENTRAL_TIME_ZONE}).format(new Date())} actions={<><button className="secondary-button" onClick={()=>openModal("lead")}><UsersRound size={17}/>Novo lead</button><button className="primary-button" onClick={()=>openModal("sale")}><Plus size={17}/>Registrar venda</button></>}/>
    {(overdue.length>0||!monthTarget)&&<div className="smart-alert"><div className="smart-alert-icon"><Sparkles size={18}/></div><div><strong>{overdue.length?"Atenção ao ritmo comercial":"Configure sua operação"}</strong><p>{overdue.length?`Você tem ${overdue.length} follow-up${overdue.length>1?"s":""} atrasado${overdue.length>1?"s":""}. `:"Cadastre metas para acompanhar o ritmo diário e mensal."}</p></div><button onClick={()=>setActive(overdue.length?"Follow-ups":"Metas")}>Ver detalhes <ChevronRight size={15}/></button></div>}
    <div className="metrics-grid"><MetricCard label="Faturamento hoje" value={money(dailyRevenue)} icon={<CircleDollarSign size={20}/>} accent="violet" detail={dailyTarget?<><span className="positive"><TrendingUp size={13}/>{pct(dailyRevenue,dailyTarget)}%</span> da meta de {money(dailyTarget)}</>:<button className="inline-link" onClick={()=>setActive("Metas")}>Definir meta diária</button>}/><MetricCard label="Meta mensal" value={`${pct(monthlyRevenue,monthTarget)}%`} icon={<Target size={20}/>} detail={monthTarget?<>{money(monthlyRevenue)} de {money(monthTarget)}</>:<button className="inline-link" onClick={()=>setActive("Metas")}>Cadastre sua meta</button>} accent="blue"/><MetricCard label="Pipeline aberto" value={money(pipelineValue)} icon={<Gauge size={20}/>} detail={<>{leads.filter(l=>!["Ganho","Perdido"].includes(l.status)).length} oportunidades ativas</>} accent="amber"/><MetricCard label="Ticket médio" value={money(avg)} icon={<Activity size={20}/>} detail={<><span className={conversion?"positive":"muted"}>{conversion}%</span> de conversão</>} accent="green"/></div>
    <div className="dashboard-grid main-chart-row"><article className="panel chart-panel"><div className="panel-head"><div><span>DESEMPENHO</span><h2>Faturamento dos últimos 7 dias</h2></div><span className="chip-button">7 dias</span></div><RevenueChart values={chart}/><div className="chart-summary"><div><span>Esta semana</span><strong>{money(weeklyRevenue)}</strong>{weekGoal?.revenueTarget?<small>{pct(weeklyRevenue,weekGoal.revenueTarget)}% da meta semanal</small>:null}</div><div><span>Hoje</span><strong>{money(dailyRevenue)}</strong>{dayGoal?.revenueTarget?<small>{pct(dailyRevenue,dayGoal.revenueTarget)}% da meta diária</small>:null}</div><div><span>Vendas hoje</span><strong>{dailySales.length}</strong></div></div></article><article className="panel goal-panel"><div className="panel-head"><div><span>RITMO DO MÊS</span><h2>Progresso da meta</h2></div><Target size={20}/></div><div className="goal-ring" style={{"--progress":`${pct(monthlyRevenue,monthTarget)*3.6}deg`} as React.CSSProperties}><div><strong>{pct(monthlyRevenue,monthTarget)}%</strong><span>atingido</span></div></div><div className="goal-numbers"><div><span>Realizado</span><strong>{money(monthlyRevenue)}</strong></div><div><span>Meta</span><strong>{money(monthTarget)}</strong></div></div>{monthTarget?<><Progress value={monthlyRevenue} target={monthTarget}/><p>Faltam <strong>{money(Math.max(0,monthTarget-monthlyRevenue))}</strong>. Projeção: <strong>{money(projection)}</strong>.</p></>:<button className="empty-action" onClick={()=>setActive("Metas")}><Plus size={16}/>Criar meta mensal</button>}</article></div>
    <div className="dashboard-grid bottom-row"><article className="panel"><div className="panel-head"><div><span>AGENDA COMERCIAL</span><h2>Follow-ups prioritários</h2></div><button className="text-button" onClick={()=>setActive("Follow-ups")}>Ver todos <ChevronRight size={15}/></button></div>{[...overdue,...todayFollowups].slice(0,4).length?<div className="compact-list">{[...overdue,...todayFollowups].slice(0,4).map(l=><div className="compact-row" key={l.id}><div className={`avatar small ${l.nextFollowup<todayISO()?"late":""}`}>{l.name.slice(0,1)}</div><div><strong>{l.name}</strong><span>{l.company||l.productInterest||"Sem empresa"}</span></div><StatusBadge>{l.nextFollowup<todayISO()?"Atrasado":"Hoje"}</StatusBadge><span className="row-value">{money(l.potentialValue)}</span></div>)}</div>:<Empty icon={<RefreshCw size={22}/>} title="Tudo em dia" text="Nenhum follow-up atrasado ou marcado para hoje."/>}</article><article className="panel"><div className="panel-head"><div><span>FOCO DE HOJE</span><h2>Próximas tarefas</h2></div><button className="text-button" onClick={()=>setActive("Tarefas")}>Ver todas <ChevronRight size={15}/></button></div>{tasks.slice(0,4).length?<div className="task-mini-list">{tasks.slice(0,4).map(t=><div className="task-mini" key={t.id}><span className={`priority-dot ${t.priority.toLowerCase()}`}/><div><strong>{t.title}</strong><span>{t.responsible||"Sem responsável"} · {shortDate(t.dueDate)}</span></div><StatusBadge>{t.priority}</StatusBadge></div>)}</div>:<Empty icon={<ClipboardCheck size={22}/>} title="Nenhuma tarefa aberta" text="Crie uma tarefa para organizar o próximo passo." action={<button className="empty-action" onClick={()=>openModal("task")}><Plus size={15}/>Nova tarefa</button>}/>}</article></div>
    <article className="panel"><div className="panel-head"><div><span>FUNIL DE VENDAS</span><h2>Distribuição das oportunidades</h2></div><button className="text-button" onClick={()=>setActive("Pipeline")}>Abrir pipeline <ChevronRight size={15}/></button></div><div className="funnel-strip">{pipelineStages.slice(0,6).map((stage,index)=>{const items=leads.filter(l=>l.status===stage);return <div key={stage}><div className={`funnel-block stage-${index}`}><strong>{items.length}</strong><span>{stage.replace(" marcada","")}</span></div>{index<5&&<ChevronRight size={16}/>}</div>;})}</div></article>
  </>;
}

function RevenueChart({values}:{values:{label:string;value:number}[]}){const max=Math.max(...values.map(i=>i.value),1),points=values.map((i,n)=>`${n*100},${160-i.value/max*130}`).join(" "),area=`0,170 ${points} 600,170`;return <div className="line-chart"><svg viewBox="0 0 600 180" preserveAspectRatio="none"><defs><linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#6d5dfc" stopOpacity=".28"/><stop offset="100%" stopColor="#6d5dfc" stopOpacity="0"/></linearGradient></defs><line x1="0" y1="40" x2="600" y2="40"/><line x1="0" y1="100" x2="600" y2="100"/><line x1="0" y1="160" x2="600" y2="160"/><polygon points={area} fill="url(#areaGradient)"/><polyline points={points} fill="none" stroke="#6d5dfc" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round" vectorEffect="non-scaling-stroke"/>{values.map((i,n)=><circle key={i.label} cx={n*100} cy={160-i.value/max*130} r="5" fill="#fff" stroke="#6d5dfc" strokeWidth="3" vectorEffect="non-scaling-stroke"/>)}</svg><div className="chart-labels">{values.map(i=><span key={i.label}>{i.label}</span>)}</div></div>;}

function Products({data,openModal,remove}:{data:WorkspaceData|null;openModal:(type:ModalType,item?:Product|Lead|null)=>void;remove:(entity:string,id:number,label:string)=>void}){const products=data?.products||[];return <><SectionHeader eyebrow="CATÁLOGO" title="Produtos e serviços" text="Preços, custos, margens e argumentos comerciais em um só lugar." actions={<button className="primary-button" onClick={()=>openModal("product")}><PackagePlus size={17}/>Novo produto</button>}/>{products.length?<div className="product-grid">{products.map(p=>{const profit=p.price-p.cost,margin=p.price?Math.round(profit/p.price*100):0;return <article className="product-card" key={p.id}><div className="product-card-head"><div className="product-glyph">{p.name.slice(0,2).toUpperCase()}</div><div className="card-actions"><button onClick={()=>openModal("product",p)}><Pencil size={16}/></button><button onClick={()=>remove("product",p.id,p.name)}><Trash2 size={16}/></button></div></div><span className="category-tag">{p.category}</span><h2>{p.name}</h2><p>{p.description||"Adicione uma descrição comercial para este produto."}</p><div className="product-price"><strong>{money(p.price)}</strong><StatusBadge>{p.status}</StatusBadge></div><div className="product-stats"><div><span>Custo</span><strong>{money(p.cost)}</strong></div><div><span>Lucro bruto</span><strong>{money(profit)}</strong></div><div><span>Margem</span><strong>{margin}%</strong></div></div><button className="card-edit" onClick={()=>openModal("product",p)}>Ver ficha comercial <ChevronRight size={16}/></button></article>;})}</div>:<div className="panel"><Empty icon={<Boxes size={26}/>} title="Seu catálogo começa aqui" text="Cadastre o primeiro produto com preço, custo e informações de venda. Nenhum dado fictício foi criado." action={<button className="primary-button" onClick={()=>openModal("product")}><Plus size={16}/>Cadastrar produto</button>}/></div>}</>;}

function Leads({data,kanban,setKanban,openModal,update,remove}:{data:WorkspaceData|null;kanban:boolean;setKanban:(v:boolean)=>void;openModal:(type:ModalType,item?:Product|Lead|null)=>void;update:(entity:string,id:number,fields:Record<string,unknown>,message?:string)=>void;remove:(entity:string,id:number,label:string)=>void}){const leads=data?.leads||[];return <><SectionHeader eyebrow="CRM" title="Leads" text={`${leads.length} contatos no total · ${money(leads.reduce((n,l)=>n+l.potentialValue,0))} em valor potencial`} actions={<><div className="view-toggle"><button className={!kanban?"active":""} onClick={()=>setKanban(false)}>Tabela</button><button className={kanban?"active":""} onClick={()=>setKanban(true)}>Kanban</button></div><button className="primary-button" onClick={()=>openModal("lead")}><Plus size={17}/>Novo lead</button></>}/>{!leads.length?<div className="panel"><Empty icon={<UsersRound size={26}/>} title="Nenhum lead cadastrado" text="Adicione o primeiro contato para começar seu pipeline." action={<button className="primary-button" onClick={()=>openModal("lead")}><Plus size={16}/>Adicionar lead</button>}/></div>:kanban?<KanbanBoard leads={leads} update={update}/>:<div className="table-panel"><table><thead><tr><th>Lead</th><th>Interesse</th><th>Responsável</th><th>Status</th><th>Próximo contato</th><th>Valor potencial</th><th/></tr></thead><tbody>{leads.map(l=><tr key={l.id}><td><div className="person-cell"><div className="avatar small">{l.name.slice(0,1)}</div><div><strong>{l.name}</strong><span>{l.company||l.email||"Sem empresa"}</span></div></div></td><td>{l.productInterest||"—"}</td><td>{l.responsible||"—"}</td><td><select className="status-select" value={l.status} onChange={e=>update("lead",l.id,{status:e.target.value},"Etapa do lead atualizada.")}>{leadStages.map(s=><option key={s}>{s}</option>)}</select></td><td><span className={l.nextFollowup&&l.nextFollowup<todayISO()?"date-late":""}>{shortDate(l.nextFollowup)}</span></td><td><strong>{money(l.potentialValue)}</strong></td><td><div className="row-actions"><button onClick={()=>openModal("lead",l)}><Pencil size={15}/></button><button onClick={()=>remove("lead",l.id,l.name)}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div>}</>;}

function KanbanBoard({leads,update}:{leads:Lead[];update:(entity:string,id:number,fields:Record<string,unknown>,message?:string)=>void}){return <div className="kanban-board">{pipelineStages.map(stage=>{const items=leads.filter(l=>l.status===stage);return <section className="kanban-column" key={stage} onDragOver={event=>event.preventDefault()} onDrop={event=>{const id=Number(event.dataTransfer.getData("text/pipeline-lead"));const lead=leads.find(item=>item.id===id);if(lead&&lead.status!==stage)update("lead",id,{status:stage},`${lead.name} movido para ${stage}.`);}}><header><div><i/><strong>{stage}</strong><span>{items.length}</span></div><b>{money(items.reduce((n,l)=>n+l.potentialValue,0))}</b></header><div className="kanban-items">{items.map(l=><article className="kanban-card" key={l.id} draggable onDragStart={event=>{event.dataTransfer.effectAllowed="move";event.dataTransfer.setData("text/pipeline-lead",String(l.id));}}><div className="kanban-top"><span>{l.company||"Contato direto"}</span><MoreHorizontal size={16}/></div><h3>{l.name}</h3><p>{l.productInterest||"Produto não definido"}</p><div className="kanban-meta"><span>{money(l.potentialValue)}</span><span><Clock3 size={13}/>{shortDate(l.nextFollowup)}</span></div><select aria-label={`Etapa de ${l.name}`} value={l.status} onChange={e=>update("lead",l.id,{status:e.target.value},"Lead movido no pipeline.")}>{leadStages.map(s=><option key={s}>{s}</option>)}</select></article>)}{!items.length&&<div className="kanban-empty">Solte uma oportunidade aqui</div>}</div></section>;})}</div>;}
function Pipeline({data,update,openModal}:{data:WorkspaceData|null;update:(e:string,id:number,f:Record<string,unknown>,m?:string)=>void;openModal:(t:ModalType)=>void}){const leads=data?.leads||[];return <><SectionHeader eyebrow="FUNIL" title="Pipeline de vendas" text={`${leads.filter(l=>!["Ganho","Perdido"].includes(l.status)).length} oportunidades abertas · ${money(leads.filter(l=>!["Ganho","Perdido"].includes(l.status)).reduce((n,l)=>n+l.potentialValue,0))} no pipeline`} actions={<button className="primary-button" onClick={()=>openModal("lead")}><Plus size={17}/>Nova oportunidade</button>}/>{leads.length?<KanbanBoard leads={leads} update={update}/>:<div className="panel"><Empty icon={<Gauge size={26}/>} title="Pipeline vazio" text="Adicione leads para acompanhar cada oportunidade até a venda."/></div>}</>;}

function Sales({data,openModal,update,remove}:{data:WorkspaceData|null;openModal:(t:ModalType)=>void;update:(e:string,id:number,f:Record<string,unknown>,m?:string)=>void;remove:(e:string,id:number,l:string)=>void}){const sales=data?.sales||[],paid=sales.filter(s=>s.status==="Pago");return <><SectionHeader eyebrow="RECEITA" title="Vendas" text={`${paid.length} vendas pagas · ${money(paid.reduce((n,s)=>n+s.finalValue,0))} de faturamento`} actions={<button className="primary-button" onClick={()=>openModal("sale")}><Plus size={17}/>Registrar venda</button>}/><div className="metrics-grid compact-metrics"><MetricCard label="Faturamento total" value={money(paid.reduce((n,s)=>n+s.finalValue,0))} detail={`${paid.length} vendas pagas`} icon={<CircleDollarSign size={19}/>} accent="violet"/><MetricCard label="A receber" value={money(sales.filter(s=>s.status==="Pendente").reduce((n,s)=>n+s.finalValue,0))} detail={`${sales.filter(s=>s.status==="Pendente").length} pendentes`} icon={<Clock3 size={19}/>} accent="amber"/><MetricCard label="Lucro bruto" value={money(paid.reduce((n,s)=>n+s.finalValue-s.cost,0))} detail="Vendas pagas menos custos" icon={<TrendingUp size={19}/>} accent="green"/></div>{sales.length?<div className="table-panel"><table><thead><tr><th>Cliente</th><th>Produto</th><th>Vendedor</th><th>Data</th><th>Valor final</th><th>Status</th><th/></tr></thead><tbody>{sales.map(s=><tr key={s.id}><td><strong>{s.client}</strong></td><td>{s.productName}</td><td>{s.seller||"—"}</td><td>{shortDate(s.date)}</td><td><strong>{money(s.finalValue)}</strong>{s.discount>0&&<span className="cell-note">-{money(s.discount)} desconto</span>}</td><td><select className="status-select" value={s.status} onChange={e=>update("sale",s.id,{status:e.target.value},e.target.value==="Pago"?"Venda paga. Dashboard atualizado.":"Status atualizado.")}><option>Pendente</option><option>Pago</option><option>Cancelado</option><option>Reembolsado</option></select></td><td><button className="table-delete" onClick={()=>remove("sale",s.id,`venda de ${s.client}`)}><Trash2 size={15}/></button></td></tr>)}</tbody></table></div>:<div className="panel"><Empty icon={<HandCoins size={26}/>} title="Nenhuma venda registrada" text="Quando uma venda for marcada como paga, todos os indicadores serão recalculados automaticamente." action={<button className="primary-button" onClick={()=>openModal("sale")}><Plus size={16}/>Registrar primeira venda</button>}/></div>}</>;}

function Goals({data,paidSales,openModal,remove}:{data:WorkspaceData|null;paidSales:Sale[];openModal:(t:ModalType,item?:Product|Lead|Goal|null)=>void;remove:(e:string,id:number,l:string)=>void}){const goals=data?.goals||[];const range=(g:Goal)=>({start:g.startDate||(g.periodType==="Diária"?todayISO():g.periodType==="Semanal"?startOfWeek():startOfMonth()),end:g.endDate||"9999-12-31"});const valuesFor=(g:Goal)=>{const {start,end}=range(g);const scopedSales=paidSales.filter(s=>s.date>=start&&s.date<=end&&(g.scope==="Empresa"||s.seller===g.ownerName));const scopedLeads=(data?.leads||[]).filter(lead=>lead.createdAt.slice(0,10)>=start&&lead.createdAt.slice(0,10)<=end&&(g.scope==="Empresa"||lead.responsible===g.ownerName));const meetings=(data?.calendarEvents||[]).filter(event=>event.category==="Reunião"&&event.status!=="Cancelado"&&event.startAt.slice(0,10)>=start&&event.startAt.slice(0,10)<=end&&(g.scope==="Empresa"||data?.teamMembers.find(member=>member.id===event.ownerId)?.name===g.ownerName)).length;return{revenue:scopedSales.reduce((sum,sale)=>sum+sale.finalValue,0),sales:scopedSales.length,leads:scopedLeads.length,meetings,proposals:scopedLeads.filter(lead=>["Proposta enviada","Negociação","Ganho"].includes(lead.status)).length};};return <><SectionHeader eyebrow="OBJETIVOS" title="Metas" text="Acompanhe faturamento, vendas, leads, reuniões e propostas com dados reais do período." actions={<button className="primary-button" onClick={()=>openModal("goal")}><Plus size={17}/>Nova meta</button>}/>{goals.length?<div className="goal-cards">{goals.map(g=>{const values=valuesFor(g);return <article className="goal-card" key={g.id}><div className="goal-card-top"><div className="goal-target-icon"><Target size={20}/></div><div><span>{g.periodType} · {g.scope}</span><h2>{g.name}</h2></div><div className="goal-card-actions"><button aria-label={`Editar ${g.name}`} onClick={()=>openModal("goal",g)}><Pencil size={16}/></button><button aria-label={`Excluir ${g.name}`} onClick={()=>remove("goal",g.id,g.name)}><Trash2 size={16}/></button></div></div><div className="goal-value"><strong>{money(values.revenue)}</strong><span>de {money(g.revenueTarget)}</span></div><Progress value={values.revenue} target={g.revenueTarget}/><div className="goal-footer"><span>{pct(values.revenue,g.revenueTarget)}% atingido</span><strong>Faltam {money(Math.max(0,g.revenueTarget-values.revenue))}</strong></div><div className="goal-mini"><span><b>{values.sales}/{g.salesTarget}</b> vendas</span><span><b>{values.leads}/{g.leadsTarget}</b> leads</span><span><b>{values.meetings}/{g.meetingsTarget}</b> reuniões</span><span><b>{values.proposals}/{g.proposalsTarget}</b> propostas</span></div></article>;})}</div>:<div className="panel"><Empty icon={<Target size={27}/>} title="Transforme objetivo em ritmo diário" text="Cadastre metas de faturamento, vendas, leads, reuniões e propostas." action={<button className="primary-button" onClick={()=>openModal("goal")}><Plus size={16}/>Criar primeira meta</button>}/></div>}</>;}

function Tasks({data,openModal,update,remove}:{data:WorkspaceData|null;openModal:(t:ModalType)=>void;update:(e:string,id:number,f:Record<string,unknown>,m?:string)=>void;remove:(e:string,id:number,l:string)=>void}){const tasks=data?.tasks||[];return <><SectionHeader eyebrow="EXECUÇÃO" title="Tarefas" text="Priorize o trabalho comercial e conecte cada próximo passo à operação." actions={<button className="primary-button" onClick={()=>openModal("task")}><Plus size={17}/>Nova tarefa</button>}/>{tasks.length?<div className="task-board">{["A fazer","Em andamento","Concluída"].map(status=><section className="task-column" key={status}><header><div><span className="task-status-dot"/><strong>{status}</strong></div><span>{tasks.filter(t=>t.status===status).length}</span></header>{tasks.filter(t=>t.status===status).map(t=><article className="task-card" key={t.id}><div className="task-card-top"><StatusBadge>{t.priority}</StatusBadge><button onClick={()=>remove("task",t.id,t.title)}><Trash2 size={15}/></button></div><h3>{t.title}</h3><p>{t.description||"Sem descrição"}</p><div className="task-card-meta"><span><CalendarDays size={14}/>{shortDate(t.dueDate)}{t.startAt?` · ${t.startAt.slice(11,16)}–${t.endAt.slice(11,16)}`:""}</span><span><UserRound size={14}/>{t.responsible||"Sem responsável"}</span></div><select value={t.status} onChange={e=>update("task",t.id,{status:e.target.value},"Tarefa atualizada.")}><option>A fazer</option><option>Em andamento</option><option>Concluída</option></select></article>)}</section>)}</div>:<div className="panel"><Empty icon={<ListTodo size={27}/>} title="Sua lista está limpa" text="Crie tarefas com responsável, prazo e prioridade." action={<button className="primary-button" onClick={()=>openModal("task")}><Plus size={16}/>Criar tarefa</button>}/></div>}</>;}

function Followups({data,today,update,openModal}:{data:WorkspaceData|null;today:string;update:(e:string,id:number,f:Record<string,unknown>,m?:string)=>void;openModal:(t:ModalType)=>void}){const leads=(data?.leads||[]).filter(l=>l.nextFollowup&&!["Ganho","Perdido"].includes(l.status));const groups=[{title:"Atrasados",items:leads.filter(l=>l.nextFollowup<today),tone:"danger"},{title:"Para hoje",items:leads.filter(l=>l.nextFollowup===today),tone:"today"},{title:"Próximos",items:leads.filter(l=>l.nextFollowup>today),tone:"future"}];return <><SectionHeader eyebrow="RELACIONAMENTO" title="Follow-ups" text="Nenhuma oportunidade fica esquecida. Atualize o próximo contato ao concluir cada ação." actions={<button className="primary-button" onClick={()=>openModal("lead")}><Plus size={17}/>Novo lead</button>}/><div className="followup-grid">{groups.map(g=><section className="panel followup-panel" key={g.title}><div className="panel-head"><div><span>{g.tone==="danger"?"AÇÃO NECESSÁRIA":g.tone==="today"?"PRIORIDADE":"PLANEJADO"}</span><h2>{g.title}</h2></div><span className={`count-badge ${g.tone}`}>{g.items.length}</span></div>{g.items.length?<div className="followup-list">{g.items.map(l=><article key={l.id}><div className="avatar small">{l.name.slice(0,1)}</div><div><strong>{l.name}</strong><span>{l.company||l.productInterest||"Contato"}</span><small>{l.status} · {money(l.potentialValue)}</small></div><div className="followup-action"><b>{shortDate(l.nextFollowup)}</b><button onClick={()=>{const next=new Date(`${l.nextFollowup}T12:00:00`);next.setDate(next.getDate()+3);update("lead",l.id,{lastContact:today,nextFollowup:next.toLocaleDateString("sv-SE")},"Follow-up concluído e próximo contato criado.");}}><Check size={15}/>Concluir</button></div></article>)}</div>:<Empty icon={<Check size={21}/>} title="Nenhum contato" text={g.tone==="danger"?"Não há follow-ups atrasados.":"Nenhum follow-up nesta categoria."}/>}</section>)}</div></>;}

function Customers({data}:{data:WorkspaceData|null}){const paid=(data?.sales||[]).filter(s=>s.status==="Pago"),customers=Array.from(new Set(paid.map(s=>s.client))).map(name=>({name,sales:paid.filter(s=>s.client===name),total:paid.filter(s=>s.client===name).reduce((n,s)=>n+s.finalValue,0)}));return <><SectionHeader eyebrow="CARTEIRA" title="Clientes" text="Clientes são formados automaticamente a partir das vendas pagas."/>{customers.length?<div className="customer-grid">{customers.map(c=><article className="customer-card" key={c.name}><div className="avatar">{c.name.slice(0,1)}</div><div><h2>{c.name}</h2><p>{c.sales.length} compra{c.sales.length!==1?"s":""}</p></div><strong>{money(c.total)}</strong><div className="customer-products">{Array.from(new Set(c.sales.map(s=>s.productName))).map(p=><span key={p}>{p}</span>)}</div></article>)}</div>:<div className="panel"><Empty icon={<BriefcaseBusiness size={27}/>} title="Nenhum cliente ainda" text="Ao marcar uma venda como paga, o cliente aparecerá automaticamente aqui."/></div>}</>;}
function Finance({data,revenue,cost,profit}:{data:WorkspaceData|null;revenue:number;cost:number;profit:number}){const paid=(data?.sales||[]).filter(s=>s.status==="Pago"&&s.date>=startOfMonth()),margin=revenue?Math.round(profit/revenue*100):0;return <><SectionHeader eyebrow="FINANCEIRO" title="Visão financeira" text="Valores calculados a partir das vendas pagas do mês atual."/><div className="metrics-grid"><MetricCard label="Faturamento" value={money(revenue)} detail={`${paid.length} vendas pagas`} icon={<WalletCards size={19}/>} accent="violet"/><MetricCard label="Custos" value={money(cost)} detail="Custos informados nas vendas" icon={<ArrowDownRight size={19}/>} accent="amber"/><MetricCard label="Lucro bruto" value={money(profit)} detail={`${margin}% de margem`} icon={<ArrowUpRight size={19}/>} accent="green"/><MetricCard label="Ticket médio" value={money(paid.length?revenue/paid.length:0)} detail="Por venda paga" icon={<Activity size={19}/>} accent="blue"/></div><article className="panel finance-list"><div className="panel-head"><div><span>TRANSAÇÕES</span><h2>Vendas pagas neste mês</h2></div></div>{paid.length?paid.map(s=><div className="finance-row" key={s.id}><div className="finance-icon"><ArrowUpRight size={17}/></div><div><strong>{s.client}</strong><span>{s.productName} · {shortDate(s.date)}</span></div><div><strong>{money(s.finalValue)}</strong><span>Lucro {money(s.finalValue-s.cost)}</span></div></div>):<Empty icon={<WalletCards size={24}/>} title="Sem movimentação" text="As vendas pagas do mês aparecerão aqui."/>}</article></>;}

// eslint-disable-next-line @typescript-eslint/no-unused-vars -- mantido como fallback visual da versão anterior
function CalendarView({data}:{data:WorkspaceData|null}){const events=[...(data?.tasks||[]).filter(i=>i.dueDate).map(i=>({date:i.dueDate,title:i.title,type:"Tarefa"})),...(data?.leads||[]).filter(i=>i.nextFollowup).map(i=>({date:i.nextFollowup,title:`Contato: ${i.name}`,type:"Follow-up"}))].sort((a,b)=>a.date.localeCompare(b.date));const monthLabel=new Intl.DateTimeFormat("pt-BR",{month:"long",year:"numeric"}).format(new Date());return <><SectionHeader eyebrow="AGENDA" title="Calendário" text="Tarefas e follow-ups reunidos por data."/><div className="calendar-layout"><article className="panel calendar-panel"><div className="calendar-head"><ChevronRight className="flip" size={18}/><h2>{monthLabel}</h2><ChevronRight size={18}/></div><MonthGrid events={events}/></article><article className="panel agenda-panel"><div className="panel-head"><div><span>PRÓXIMOS</span><h2>Agenda</h2></div></div>{events.filter(e=>e.date>=todayISO()).slice(0,8).map((e,i)=><div className="agenda-row" key={`${e.date}-${i}`}><div><strong>{new Date(`${e.date}T12:00:00`).getDate()}</strong><span>{new Intl.DateTimeFormat("pt-BR",{month:"short"}).format(new Date(`${e.date}T12:00:00`))}</span></div><div><strong>{e.title}</strong><span>{e.type}</span></div></div>)}</article></div></>;}
function MonthGrid({events}:{events:{date:string;title:string;type:string}[]}){const now=new Date(),first=new Date(now.getFullYear(),now.getMonth(),1),total=new Date(now.getFullYear(),now.getMonth()+1,0).getDate(),offset=first.getDay(),cells=Array.from({length:42},(_,i)=>i-offset+1);return <div className="month-grid"><div className="weekdays">{["DOM","SEG","TER","QUA","QUI","SEX","SÁB"].map(d=><span key={d}>{d}</span>)}</div><div className="days-grid">{cells.map((day,i)=>{const valid=day>0&&day<=total,date=valid?`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}-${String(day).padStart(2,"0")}`:"",count=events.filter(e=>e.date===date).length;return <div className={`${valid?"":"muted-day"} ${date===todayISO()?"today-day":""}`} key={i}><span>{valid?day:""}</span>{count>0&&<i>{count}</i>}</div>;})}</div></div>;}

function Reports({data,exportCsv}:{data:WorkspaceData|null;exportCsv:(k:"leads"|"sales"|"products")=>void}){const reports=[{key:"leads" as const,title:"Relatório de leads",text:`${data?.leads.length||0} contatos e oportunidades`,icon:<UsersRound/>},{key:"sales" as const,title:"Relatório de vendas",text:`${data?.sales.length||0} registros comerciais`,icon:<HandCoins/>},{key:"products" as const,title:"Catálogo de produtos",text:`${data?.products.length||0} produtos e serviços`,icon:<Boxes/>}];return <><SectionHeader eyebrow="EXPORTAÇÃO" title="Relatórios" text="Exporte dados reais da operação em CSV para análise ou compartilhamento."/><div className="report-grid">{reports.map(r=><article className="report-card" key={r.key}><div>{r.icon}</div><h2>{r.title}</h2><p>{r.text}</p><button className="secondary-button" onClick={()=>exportCsv(r.key)}><Download size={16}/>Exportar CSV</button></article>)}</div><article className="panel audit-panel"><div className="panel-head"><div><span>HISTÓRICO</span><h2>Alterações recentes</h2></div></div>{data?.auditLogs.length?data.auditLogs.map(log=><div className="audit-row" key={log.id}><div className="activity-dot"/><div><strong>{log.actor} {log.action} {log.entity}</strong><span>{log.detail}</span></div><time>{dateTime(log.createdAt)}</time></div>):<Empty icon={<Activity size={23}/>} title="Sem alterações registradas" text="As ações da equipe aparecerão aqui."/>}</article></>;}
function Insights({data,monthlyRevenue,monthlyProfit,pipelineValue,monthGoal}:{data:WorkspaceData|null;monthlyRevenue:number;monthlyProfit:number;pipelineValue:number;monthGoal?:Goal}){const paid=(data?.sales||[]).filter(s=>s.status==="Pago"&&s.date>=startOfMonth()),productRevenue=paid.reduce<Record<string,number>>((a,s)=>{a[s.productName]=(a[s.productName]||0)+s.finalValue;return a;},{}),top=Object.entries(productRevenue).sort((a,b)=>b[1]-a[1])[0],remaining=Math.max(0,(monthGoal?.revenueTarget||0)-monthlyRevenue),daysLeft=Math.max(1,new Date(new Date().getFullYear(),new Date().getMonth()+1,0).getDate()-new Date().getDate());const insights=[paid.length?{title:"Produto com maior faturamento",value:top?top[0]:"—",text:top?`${money(top[1])} no mês atual.`:"Sem dados.",icon:<Boxes/>}:null,monthGoal?.revenueTarget?{title:"Ritmo necessário",value:money(remaining/daysLeft),text:"por dia para alcançar a meta mensal.",icon:<Target/>}:null,data?.leads.length?{title:"Oportunidades abertas",value:money(pipelineValue),text:`em ${data.leads.filter(l=>!["Ganho","Perdido"].includes(l.status)).length} oportunidades ativas.`,icon:<Gauge/>}:null,paid.length?{title:"Margem bruta do mês",value:`${monthlyRevenue?Math.round(monthlyProfit/monthlyRevenue*100):0}%`,text:`${money(monthlyProfit)} de lucro bruto.`,icon:<TrendingUp/>}:null].filter(Boolean) as {title:string;value:string;text:string;icon:ReactNode}[];return <><SectionHeader eyebrow="INTELIGÊNCIA COMERCIAL" title="Insights" text="Leituras automáticas geradas somente quando há dados suficientes."/>{insights.length?<div className="insight-grid">{insights.map(i=><article className="insight-card" key={i.title}><div className="insight-icon">{i.icon}</div><span>{i.title}</span><strong>{i.value}</strong><p>{i.text}</p></article>)}</div>:<div className="panel"><Empty icon={<Lightbulb size={27}/>} title="Ainda estamos aprendendo" text="Cadastre produtos, leads, metas e vendas para liberar insights confiáveis. Nenhum número será inventado."/></div>}</>;}
function Configuration({data,api,user}:{data:WorkspaceData|null;api:(m:"POST"|"PATCH"|"DELETE",b:Record<string,unknown>,s:string)=>Promise<boolean>;user:string}){const[company,setCompany]=useState(data?.settings.companyName||"");return <><SectionHeader eyebrow="ADMINISTRAÇÃO" title="Configurações" text="Personalize a identidade, os acessos e a equipe do sistema."/><div className="settings-grid"><form className="panel settings-form" onSubmit={e=>{e.preventDefault();void api("POST",{entity:"setting",key:"companyName",value:company},"Nome da empresa atualizado.");}}><div className="panel-head"><div><span>IDENTIDADE</span><h2>Informações da empresa</h2></div></div><label>Nome exibido<input value={company} onChange={e=>setCompany(e.target.value)} placeholder="Nome da empresa"/></label><label>Moeda<select defaultValue="BRL"><option value="BRL">Real brasileiro (BRL)</option></select></label><button className="primary-button" type="submit">Salvar alterações</button></form><LeadStatusSettings settings={data?.settings||{}} api={api}/><article className="panel team-panel"><div className="panel-head"><div><span>SESSÃO ATUAL</span><h2>Usuário autenticado</h2></div></div><div className="team-row"><div className="avatar">{user.slice(0,1)}</div><div><strong>{user}</strong><span>Identidade fornecida pelo ChatGPT</span></div><StatusBadge>Ativo</StatusBadge></div><div className="permission-note"><UserRound size={18}/><p>Os e-mails abaixo vinculam cada integrante às áreas protegidas de documentos e inteligência artificial.</p></div></article><TeamEditor members={data?.teamMembers||[]} api={api}/></div></>;}

function RecordModal({type,editing,products,user,saving,close,submit}:{type:Exclude<ModalType,null>;editing:Product|Lead|Goal|null;products:Product[];user:string;saving:boolean;close:()=>void;submit:(e:FormEvent<HTMLFormElement>)=>void}){const item=editing as unknown as Record<string,unknown>|null,value=(key:string)=>String(item?.[key]??""),date=todayISO(),feminine=["sale","task","goal"].includes(type);return <div className="modal-layer" role="dialog" aria-modal="true"><button className="modal-scrim" onClick={close}/><div className="modal-card"><header><div><span>{editing?"EDITAR":"NOVO REGISTRO"}</span><h2>{editing?`Editar ${modalLabel(type).toLowerCase()}`:`Nov${feminine?"a":"o"} ${modalLabel(type).toLowerCase()}`}</h2></div><button onClick={close}><X size={20}/></button></header><form onSubmit={submit}><div className="form-grid">
  {type==="product"&&<><label className="full">Nome do produto<input name="name" defaultValue={value("name")} required autoFocus/></label><label>Categoria<input name="category" defaultValue={value("category")} placeholder="Ex.: Sites"/></label><label>Status<select name="status" defaultValue={value("status")||"Ativo"}><option>Ativo</option><option>Arquivado</option></select></label><label>Preço padrão<input name="price" type="number" step="0.01" min="0" defaultValue={value("price")} required/></label><label>Custo<input name="cost" type="number" step="0.01" min="0" defaultValue={value("cost")}/></label><label>Preço mínimo<input name="minimumPrice" type="number" step="0.01" min="0" defaultValue={value("minimumPrice")}/></label><label>Prazo de entrega (dias)<input name="deliveryDays" type="number" min="0" defaultValue={value("deliveryDays")}/></label><label className="full">Descrição<textarea name="description" defaultValue={value("description")}/></label><label>Público-alvo<textarea name="targetAudience" defaultValue={value("targetAudience")}/></label><label>Problema que resolve<textarea name="problemSolved" defaultValue={value("problemSolved")}/></label><label className="full">Argumentos de venda<textarea name="salesArguments" defaultValue={value("salesArguments")}/></label></>}
  {type==="lead"&&<><label>Nome<input name="name" defaultValue={value("name")} required autoFocus/></label><label>Empresa<input name="company" defaultValue={value("company")}/></label><label>WhatsApp<input name="whatsapp" defaultValue={value("whatsapp")}/></label><label>Email<input name="email" type="email" defaultValue={value("email")}/></label><label>Segmento<input name="segment" defaultValue={value("segment")}/></label><label>Cidade<input name="city" defaultValue={value("city")}/></label><label>Produto de interesse<input name="productInterest" defaultValue={value("productInterest")} list="product-options"/><datalist id="product-options">{products.map(p=><option key={p.id} value={p.name}/>)}</datalist></label><label>Valor potencial<input name="potentialValue" type="number" step="0.01" min="0" defaultValue={value("potentialValue")}/></label><label>Responsável<input name="responsible" defaultValue={value("responsible")||user}/></label><label>Status<select name="status" defaultValue={value("status")||"Novo"}>{leadStages.map(s=><option key={s}>{s}</option>)}</select></label><label>Origem<select name="source" defaultValue={value("source")||"Indicação"}><option>Indicação</option><option>Prospecção ativa</option><option>Google Maps</option><option>Instagram</option><option>Site</option><option>Outro</option></select></label><label>Próximo follow-up<input name="nextFollowup" type="date" defaultValue={value("nextFollowup")}/></label><label className="full">Observações<textarea name="notes" defaultValue={value("notes")}/></label></>}
  {type==="sale"&&<><label>Cliente<input name="client" required autoFocus/></label><label>Produto<select name="productName" required defaultValue=""><option value="" disabled>Selecione</option>{products.map(p=><option key={p.id} value={p.name}>{p.name}</option>)}</select></label><label>Valor bruto<input name="grossValue" type="number" min="0" step="0.01" required/></label><label>Desconto<input name="discount" type="number" min="0" step="0.01" defaultValue="0"/></label><label>Custo da venda<input name="cost" type="number" min="0" step="0.01" defaultValue="0"/></label><label>Vendedor<input name="seller" defaultValue={user}/></label><label>Forma de pagamento<select name="paymentMethod"><option>Pix</option><option>Cartão</option><option>Boleto</option><option>Transferência</option><option>Dinheiro</option></select></label><label>Status<select name="status" defaultValue="Pendente"><option>Pendente</option><option>Pago</option><option>Cancelado</option><option>Reembolsado</option></select></label><label>Data<input name="date" type="date" defaultValue={date}/></label><label className="full">Observações<textarea name="notes"/></label></>}
  {type==="task"&&<><label className="full">Título<input name="title" required autoFocus/></label><label>Responsável<input name="responsible" defaultValue={user}/></label><label>Data da tarefa<input name="dueDate" type="date" defaultValue={date}/></label><label>Início<input name="startAt" type="datetime-local" defaultValue={`${date}T09:00`}/></label><label>Término<input name="endAt" type="datetime-local" defaultValue={`${date}T10:00`}/></label><label>Prioridade<select name="priority" defaultValue="Média"><option>Baixa</option><option>Média</option><option>Alta</option><option>Urgente</option></select></label><label>Status<select name="status"><option>A fazer</option><option>Em andamento</option><option>Concluída</option></select></label><label>Lembrete<select name="reminderMinutes" defaultValue="15"><option value="0">Sem lembrete</option><option value="5">5 minutos antes</option><option value="15">15 minutos antes</option><option value="30">30 minutos antes</option><option value="60">1 hora antes</option></select></label><label>Cor no calendário<input name="calendarColor" type="color" defaultValue="#db8a19"/></label><label className="full">Descrição<textarea name="description"/></label></>}
  {type==="goal"&&<><label className="full">Nome da meta<input name="name" defaultValue={value("name")} required autoFocus placeholder="Ex.: Meta mensal da empresa"/></label><label>Escopo<select name="scope" defaultValue={value("scope")||"Empresa"}><option>Empresa</option><option>Individual</option></select></label><label>Responsável<input name="ownerName" defaultValue={value("ownerName")||"Empresa"}/></label><label>Período<select name="periodType" defaultValue={value("periodType")||"Mensal"}><option>Diária</option><option>Semanal</option><option>Mensal</option><option>Anual</option></select></label><label>Meta de faturamento<input name="revenueTarget" type="number" min="0" step="0.01" defaultValue={value("revenueTarget")} required/></label><label>Meta de vendas<input name="salesTarget" type="number" min="0" defaultValue={value("salesTarget")}/></label><label>Meta de leads<input name="leadsTarget" type="number" min="0" defaultValue={value("leadsTarget")}/></label><label>Meta de reuniões<input name="meetingsTarget" type="number" min="0" defaultValue={value("meetingsTarget")}/></label><label>Meta de propostas<input name="proposalsTarget" type="number" min="0" defaultValue={value("proposalsTarget")}/></label><label>Início<input name="startDate" type="date" defaultValue={value("startDate")}/></label><label>Fim<input name="endDate" type="date" defaultValue={value("endDate")}/></label></>}
  </div><footer><button type="button" className="secondary-button" onClick={close}>Cancelar</button><button type="submit" className="primary-button" disabled={saving}>{saving?<LoaderCircle className="spin" size={17}/>:<Check size={17}/>} {editing?"Salvar alterações":"Criar registro"}</button></footer></form></div></div>;}
function modalLabel(type:Exclude<ModalType,null>){return({product:"Produto",lead:"Lead",sale:"Venda",task:"Tarefa",goal:"Meta"})[type];}
function lastSevenDays(sales:Sale[]){return Array.from({length:7},(_,i)=>{const date=new Date();date.setDate(date.getDate()-(6-i));const iso=date.toLocaleDateString("sv-SE",{timeZone:"America/Sao_Paulo"});return{label:new Intl.DateTimeFormat("pt-BR",{weekday:"short"}).format(date).replace(".",""),value:sales.filter(s=>s.status==="Pago"&&s.date===iso).reduce((n,s)=>n+s.finalValue,0)};});}
